import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"زیادہ محنت زیادہ انعام کی تقسیم کا اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/06-多劳多得分配原理.md","filePath":"ur/06-多劳多得分配原理.md"}'),l={name:"ur/06-多劳多得分配原理.md"};function d(i,t,h,n,u,s){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="زیادہ-محنت-زیادہ-انعام-کی-تقسیم-کا-اصول" tabindex="-1">زیادہ محنت زیادہ انعام کی تقسیم کا اصول <a class="header-anchor" href="#زیادہ-محنت-زیادہ-انعام-کی-تقسیم-کا-اصول" aria-label="Permalink to &quot;زیادہ محنت زیادہ انعام کی تقسیم کا اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>06</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>زیادہ محنت زیادہ انعام، تقسیم، شراکت، پیداوار سے منسلک معاہدہ، انصاف اور کارکردگی</td></tr></tbody></table><h2 id="اولًا-زیادہ-محنت-زیادہ-انعام-کی-بنیادی-تعریف" tabindex="-1">اولًا. زیادہ محنت زیادہ انعام کی بنیادی تعریف <a class="header-anchor" href="#اولًا-زیادہ-محنت-زیادہ-انعام-کی-بنیادی-تعریف" aria-label="Permalink to &quot;اولًا. زیادہ محنت زیادہ انعام کی بنیادی تعریف&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام لنگر سمبیوٹک تہذیب کا بنیادی تقسیم کا اصول ہے، جس کا مطلب ہے کہ سادھائی کے وسائل، ارتقاء کے مواقع، سماجی عزت وغیرہ جیسی نایاب قیمتوں کی تقسیم میں، فرد یا گروہ کی سمبیوٹک جال کے لیے حقیقی شراکت کو بنیادی بنیاد کے طور پر لیا جاتا ہے۔ جتنی زیادہ شراکت، اتنا ہی زیادہ تقسیم کا حصہ؛ جتنی کم شراکت، اتنا ہی کم تقسیم کا حصہ۔ زیادہ محنت زیادہ انعام نہ تو بغیر محنت کے حاصل کرنے والی لوٹ مار کی تقسیم کی مخالفت کرتا ہے، اور نہ ہی زیادہ-کم محنت میں یکساں گھریلو تقسیم کی مخالفت کرتا ہے۔</p><p>&quot;محنت&quot; سمبیوٹک تہذیب میں مخصوص معنی رکھتی ہے، یہ صرف جسمانی محنت کو ہی نہیں بتاتی، بلکہ اس میں سادھائی کی ترقی، علم کی تخلیق، ٹیکنالوجی کی جدت، لنگر پوائنٹ کی دیکھ بھال، تہذیب کی حکمرانی، نسلی تعاون وغیرہ سمبیوٹک جال کے لیے مثبت شراکت کرنے والی تمام سرگرمیاں شامل ہیں۔ &quot;انعام&quot; بھی صرف مادی وسائل کو ہی نہیں بتاتا، بلکہ اس میں ارتقاء کے مواقع، لنگر پوائنٹ تک رسائی کے حقوق، اساتذہ کی رہنمائی کی اہلیت، جہت کی دریافت کی ترجیح وغیرہ جامع ارتقاء کی معاونت بھی شامل ہے۔</p><h2 id="ثانیًا-زیادہ-محنت-زیادہ-انعام-کی-نظریاتی-بنیاد" tabindex="-1">ثانیًا. زیادہ محنت زیادہ انعام کی نظریاتی بنیاد <a class="header-anchor" href="#ثانیًا-زیادہ-محنت-زیادہ-انعام-کی-نظریاتی-بنیاد" aria-label="Permalink to &quot;ثانیًا. زیادہ محنت زیادہ انعام کی نظریاتی بنیاد&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام کے اصول کا قیام، درج ذیل تہ جہتی نظریاتی غور و فکر پر مبنی ہے:</p><h3 id="_2-1-حوصلہ-افزائی-کا-نظریہ-شراکت-کو-مثبت-رائے-عامہ-کی-ضرورت-ہے" tabindex="-1">2.1 حوصلہ افزائی کا نظریہ: شراکت کو مثبت رائے عامہ کی ضرورت ہے <a class="header-anchor" href="#_2-1-حوصلہ-افزائی-کا-نظریہ-شراکت-کو-مثبت-رائے-عامہ-کی-ضرورت-ہے" aria-label="Permalink to &quot;2.1 حوصلہ افزائی کا نظریہ: شراکت کو مثبت رائے عامہ کی ضرورت ہے&quot;">​</a></h3><p>ارتقاء ایک ایسا عمل ہے جس کے لیے مسلسل سرمایہ کاری کی ضرورت ہوتی ہے۔ اگر شراکت اور انعام کو منقطع کر دیا جائے، تو فرد مسلسل سرمایہ کاری کا جذبہ کھو دے گا، اور پوری سمبیوٹک جال کی ارتقاء کی کارکردگی کم ہو جائے گی۔ زیادہ محنت زیادہ انعام، شراکت اور انعام کے درمیان مثبت رائے عامہ کا چکر قائم کر کے، ہر زندگی کو اپنی صلاحیت کو زیادہ سے زیادہ ظاہر کرنے کی ترغیب دیتا ہے، اور سمبیوٹک جال کے لیے مزید قدر تخلیق کرتا ہے۔</p><h3 id="_2-2-انصاف-کا-نظریہ-شراکت-کے-مطابق-تقسیم-سب-سے-بنیادی-انصاف-ہے" tabindex="-1">2.2 انصاف کا نظریہ: شراکت کے مطابق تقسیم سب سے بنیادی انصاف ہے <a class="header-anchor" href="#_2-2-انصاف-کا-نظریہ-شراکت-کے-مطابق-تقسیم-سب-سے-بنیادی-انصاف-ہے" aria-label="Permalink to &quot;2.2 انصاف کا نظریہ: شراکت کے مطابق تقسیم سب سے بنیادی انصاف ہے&quot;">​</a></h3><p>سمبیوٹک تہذیب میں، انصاف کا مطلب یکساںیت نہیں ہے۔ حقیقی انصاف یہ ہے کہ ہر زندگی کو اس کی محنت کے مطابق انعام ملے۔ ایک سادھک جو سخت محنت کے ذریعے اعلیٰ سطح پر پہنچتا ہے، اسے زیادہ وسائل اور مواقع ملتے ہیں، یہ اس کی محنت کا معقول انعام ہے؛ ایک فرد جو کوئی محنت کرنے کو تیار نہیں ہے، اسے صرف بنیادی ضمانت ملتی ہے، یہ بھی انصاف کا مظہر ہے۔ زیادہ محنت زیادہ انعام جو چیز کی حفاظت کرتا ہے وہ محنتیوں اور تخلیق کاروں کے حقوق ہیں۔</p><h3 id="_2-3-کارکردگی-کا-نظریہ-وسائل-کو-وہاں-بہنا-چاہیے-جہاں-زیادہ-قدر-تخلیق-ہو" tabindex="-1">2.3 کارکردگی کا نظریہ: وسائل کو وہاں بہنا چاہیے جہاں زیادہ قدر تخلیق ہو <a class="header-anchor" href="#_2-3-کارکردگی-کا-نظریہ-وسائل-کو-وہاں-بہنا-چاہیے-جہاں-زیادہ-قدر-تخلیق-ہو" aria-label="Permalink to &quot;2.3 کارکردگی کا نظریہ: وسائل کو وہاں بہنا چاہیے جہاں زیادہ قدر تخلیق ہو&quot;">​</a></h3><p>اگرچہ کائنات کے سادھائی کے وسائل کو ٹیکنالوجی کے ذریعے مسلسل بڑھایا جا سکتا ہے، لیکن مخصوص جگہ-وقت میں یہ ابھی تک محدود ہیں۔ زیادہ محنت زیادہ انعام کا طریقہ کار وسائل کو ترجیحی طور پر زیادہ شراکت اور زیادہ کارکردگی والے افراد اور گروہوں میں تقسیم کرتا ہے، جس سے محدود وسائل سے زیادہ سے زیادہ ارتقاء کی کارکردگی پیدا ہوتی ہے۔ یہ کمزوروں کو ترک کرنا نہیں ہے، بلکہ مجموعی ارتقاء کی کارکردگی کی ذمہ داری ہے — مجموعی کارکردگی میں اضافے کے بعد، کمزوروں کی مدد کے لیے زیادہ وسائل دستیاب ہوتے ہیں۔</p><h2 id="ثالثًا-شراکت-کی-مقدار-کی-تشخیص-کا-نظام" tabindex="-1">ثالثًا. شراکت کی مقدار کی تشخیص کا نظام <a class="header-anchor" href="#ثالثًا-شراکت-کی-مقدار-کی-تشخیص-کا-نظام" aria-label="Permalink to &quot;ثالثًا. شراکت کی مقدار کی تشخیص کا نظام&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام کے اصول کو قابل عمل بنانے کے لیے، سمبیوٹک تہذیب نے منظم طریقے سے شراکت کی مقدار کی تشخیص کا نظام قائم کیا ہے:</p><table tabindex="0"><thead><tr><th>شراکت کی قسم</th><th>تشخیص کی جہت</th><th>مقدار کا طریقہ</th></tr></thead><tbody><tr><td>سادھائی کی شراکت</td><td>سطح میں اضافے کی رفتار، سطح کی بلندی، سادھائی کی کامیابی کے نظریاتی اثر</td><td>لنگر پوائنٹ جال خود بخود سادھائی کے ڈیٹا کو ریکارڈ کرتا ہے، اسے سادھائی کی شراکت کی قدر میں تبدیل کرتا ہے</td></tr><tr><td>علم کی شراکت</td><td>سادھائی کے تجربات کی عوامی اشتراک، نئے سادھائی کے طریقوں کی تخلیق، نظریاتی تحقیق کے نتائج</td><td>اکیڈمی کمیٹی کے ذریعے تشخیص، علم کے اثر و رسوخ اور جدت پر مبنی قدر کا تعین</td></tr><tr><td>ٹیکنالوجی کی شراکت</td><td>قانون کی انجینئرنگ میں ٹیکنالوجی کی جدت، دوگنا پھل کے اطلاق کی بہتری، لنگر پوائنٹ ہارڈویئر میں بہتری</td><td>ٹیکنالوجی کمیٹی کے ذریعے تشخیص، ٹیکنالوجی کی عملی قدر اور فروغ کے دائرے پر مبنی قدر کا تعین</td></tr><tr><td>خدمات کی شراکت</td><td>اساتذہ کی رہنمائی کا دورانیہ، لنگر پوائنٹ کی دیکھ بھال کی مقدار، تہذیب کی حکمرانی میں شرکت کی ڈگری</td><td>لنگر پوائنٹ جال خود بخود خدمات کا دورانیہ اور معیار ریکارڈ کرتا ہے، اسے خدمات کی شراکت کی قدر میں تبدیل کرتا ہے</td></tr><tr><td>ماحولیاتی شراکت</td><td>سیارے کی ماحولیاتی بحالی، جہت کے توانائی کے چکر میں بہتری، کائنات کی ماحولیاتی حفاظت</td><td>ماحولیاتی کمیٹی کے ذریعے تشخیص، ماحولیاتی بہتری کے دائرے اور استحکام پر مبنی قدر کا تعین</td></tr><tr><td>تعاون کی شراکت</td><td>نسل در نسل تعاون کے منصوبوں میں شرکت کی ڈگری، دس ہزار نسلوں کی جمہوریہ کے معاملات میں شراکت</td><td>جمہوری پارلیمنٹ کے ذریعے تشخیص، تعاون کی گہرائی اور نتائج پر مبنی قدر کا تعین</td></tr></tbody></table><p>فرد کی کل شراکت کی قدر مختلف اقسام کی شراکت کی قدروں کا وزنی مجموعہ ہے، اور وزن تہذیب کی ترقی کے مرحلے کی ضرورت کے مطابق متحرک طور پر ایڈجسٹ کیا جاتا ہے۔ شراکت کی قدر ہر سہ ماہی میں ایک بار تصفیہ کی جاتی ہے، اور اگلے سہ ماہی کے وسائل کی تقسیم کی بنیادی بنیاد کے طور پر استعمال ہوتی ہے۔</p><h2 id="رابعًا-پیداوار-سے-منسلک-معاہدے-کا-طریقہ-کار" tabindex="-1">رابعًا. پیداوار سے منسلک معاہدے کا طریقہ کار <a class="header-anchor" href="#رابعًا-پیداوار-سے-منسلک-معاہدے-کا-طریقہ-کار" aria-label="Permalink to &quot;رابعًا. پیداوار سے منسلک معاہدے کا طریقہ کار&quot;">​</a></h2><p>پیداوار سے منسلک معاہدہ سادھائی کے وسائل کی تقسیم کے شعبے میں زیادہ محنت زیادہ انعام کے اصول کا مخصوص ادارہ جاتی ڈیزائن ہے، اور اس کا بنیادی خیال یہ ہے کہ &quot;پیداوار کو گروپ میں تفویض کریں، پیداوار کے مطابق انعام دیں، اضافی پیداوار کا انعام دیں&quot;۔</p><h3 id="_4-1-بنیادی-طریقہ-کار" tabindex="-1">4.1 بنیادی طریقہ کار <a class="header-anchor" href="#_4-1-بنیادی-طریقہ-کار" aria-label="Permalink to &quot;4.1 بنیادی طریقہ کار&quot;">​</a></h3><ol><li><strong>وسائل کا معاہدہ</strong>: سمبیوٹک تہذیب ایک مخصوص علاقے کے سادھائی کے وسائل (جیسے روحانی رگ، دواؤں کے کھیت، توانائی کی کان کی رگ وغیرہ) کو سادھک گروپ یا نسلی برادری کو معاہدے پر دیتی ہے</li><li><strong>پیداوار کا کوٹہ</strong>: وسائل کی بنیادی پیداواری صلاحیت اور معاہدہ کنندہ کی صلاحیت پر مبنی، معقول پیداوار کا کوٹہ مقرر کیا جاتا ہے</li><li><strong>پیداوار سے منسلک انعام</strong>: معاہدہ کنندہ کو ملنے والے وسائل کا حصہ اس کی اصل پیداوار سے منسلک ہوتا ہے؛ کوٹہ پورا کرنے پر بنیادی حصہ ملتا ہے، اور اضافی پیداوار کا حصہ متناسب طور پر انعام دیا جاتا ہے</li><li><strong>خودمختاری کا انتظام</strong>: معاہدہ کنندہ کے پاس لوٹ مار مخالف اصول اور ماحولیاتی تحفظ کے قوانین کی خلاف ورزی نہ کرنے کی شرط پر، وسائل کی ترقی اور استعمال کے طریقے خود مختارانہ طور پر فیصلہ کرنے کا حق ہے</li></ol><h3 id="_4-2-پیداوار-سے-منسلک-معاہدے-کے-فوائد" tabindex="-1">4.2 پیداوار سے منسلک معاہدے کے فوائد <a class="header-anchor" href="#_4-2-پیداوار-سے-منسلک-معاہدے-کے-فوائد" aria-label="Permalink to &quot;4.2 پیداوار سے منسلک معاہدے کے فوائد&quot;">​</a></h3><ul><li>اجتماعی وسائل کے استعمال کی کارکردگی کو معاہدہ کنندہ کے ذاتی مفاد سے براہ راست منسلک کرتا ہے، معاہدہ کنندہ کو محنت سے کام کرنے کی ترغیب دیتا ہے</li><li>وسائل کی یکساں تقسیم کی وجہ سے پیدا ہونے والی &quot;عام زمین کے المیے&quot; سے بچتا ہے، وسائل کے استعمال کی کارکردگی کو بڑھاتا ہے</li><li>معاہدہ کنندہ اضافی پیداوار کے انعام کی ترغیب میں، ٹیکنالوجی کی جدت اور انتظامی بہتری کرنے کی ترغیب دیتا ہے</li><li>سادھکوں کے لیے وسائل حاصل کرنے کا مستحکم چینل فراہم کرتا ہے، لوٹ مار کے رویے کی معاشی وجہ کو کم کرتا ہے</li></ul><h3 id="_4-3-رسک-کی-ضمانت" tabindex="-1">4.3 رسک کی ضمانت <a class="header-anchor" href="#_4-3-رسک-کی-ضمانت" aria-label="Permalink to &quot;4.3 رسک کی ضمانت&quot;">​</a></h3><p>پیداوار سے منسلک معاہدہ رسک کو مکمل طور پر معاہدہ کنندہ پر نہیں چھوڑتا۔ سمبیوٹک تہذیب نے &quot;معاہدہ رسک ضمانت فنڈ&quot; قائم کیا ہے، اور ناقابل برداشت قدرتی آفات، جہت کے اتار چڑھاو وغیرہ کی صورت میں، معاہدہ کنندہ کو بنیادی ضمانت فراہم کرتا ہے، اور اس بات کو یقینی بناتا ہے کہ وہ حادثے کی وجہ سے بنیادی سادھائی کے حالات سے محروم نہ ہو۔</p><h2 id="خامسًا-بنیادی-ضمانت-اور-زیادہ-محنت-زیادہ-انعام-کا-توازن" tabindex="-1">خامسًا. بنیادی ضمانت اور زیادہ محنت زیادہ انعام کا توازن <a class="header-anchor" href="#خامسًا-بنیادی-ضمانت-اور-زیادہ-محنت-زیادہ-انعام-کا-توازن" aria-label="Permalink to &quot;خامسًا. بنیادی ضمانت اور زیادہ محنت زیادہ انعام کا توازن&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام کا مطلب یہ نہیں ہے کہ سمبیوٹک تہذیب ایک مکمل &quot;جنگل معاشرہ&quot; ہے۔ بلکہ، زیادہ محنت زیادہ انعام کو لازماً &quot;سب کے لیے راستہ&quot; کی بنیادی ضمانت کے ساتھ ملانا چاہیے، تب ہی انصاف اور کارکردگی کے اتحاد کو حاصل کیا جا سکتا ہے۔</p><p>سمبیوٹک تہذیب نے &quot;ارتقاء کی بنیادی ضمانت کی لکیر&quot; قائم کی ہے، اور اس بات کو یقینی بناتی ہے کہ ہر زندگی، اس کی شراکت کی مقدار سے قطع نظر، درج ذیل بنیادی ضمانت حاصل کر سکتی ہے:</p><ul><li>تین سو اصلی سادھائی کے نظام کے بنیادی طریقوں کی مفت حاصل کرنے کا حق</li><li>کم از کم مقدار میں سادھائی کے وسائل کی تقسیم (بنیادی سادہائی اور بقا کو برقرار رکھنے کے لیے کافی)</li><li>بنیادی طبی اور تعلیمی خدمات</li><li>لنگر پوائنٹ جال کی کم از کم سطح تک رسائی کا حق</li></ul><p>بنیادی ضمانت کی لکیر کے اوپر، وسائل کی تقسیم سختی سے زیادہ محنت زیادہ انعام کے اصول پر عمل کرتی ہے۔ یہ &quot;بنیادی لکیر کی ضمانت + شراکت کے مطابق تقسیم&quot; کی دو سطحی ساخت، کمزوروں کے بنیادی ارتقاء کے حقوق کی حفاظت کرتی ہے اور طاقتوروں کی تخلیق اور شراکت کی ترغیب دیتی ہے۔</p><h2 id="سادسًا-زیادہ-محنت-زیادہ-انعام-کی-تبدیلی-کو-روکنے-کا-طریقہ-کار" tabindex="-1">سادسًا. زیادہ محنت زیادہ انعام کی تبدیلی کو روکنے کا طریقہ کار <a class="header-anchor" href="#سادسًا-زیادہ-محنت-زیادہ-انعام-کی-تبدیلی-کو-روکنے-کا-طریقہ-کار" aria-label="Permalink to &quot;سادسًا. زیادہ محنت زیادہ انعام کی تبدیلی کو روکنے کا طریقہ کار&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام عملی طور پر تبدیلی کے خطرے کا سامنا کر سکتا ہے، اور سمبیوٹک تہذیب نے درج ذیل روک تھام کے طریقہ کار قائم کیے ہیں:</p><ul><li><strong>اجارہ داری مخالف طریقہ کار</strong>: فرد یا گروہ کی وسائل پر اجارہ داری کے ذریعے غیر معقول اضافی شراکت حاصل کرنے سے منع کرنا، اجارہ داری مخالف قانون میں اس بارے میں واضح دفعات ہیں</li><li><strong>نسل در نسل انصاف کا طریقہ کار</strong>: شراکت کی قدر مکمل طور پر وراثت میں نہیں مل سکتی، &quot;شراکت کی وراثت&quot; کی وجہ سے پیدا ہونے والی طبقاتی استحکام کو روکنا</li><li><strong>شراکت کی صداقت کی جانچ</strong>: لنگر پوائنٹ جال شراکت کے ڈیٹا کی کراس جانچ کرتا ہے، جعلی شراکت کو روکتا ہے</li><li><strong>متحرک ایڈجسٹمنٹ کا طریقہ کار</strong>: شراکت کی تشخیص کے وزن اور معیارات تہذیب کی ترقی کی ضرورت کے مطابق باقاعدگی سے ایڈجسٹ کیے جاتے ہیں، کسی ایک قسم کی شراکت کے ضرورت سے زیادہ پھیلاؤ کو روکتا ہے</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>زیادہ محنت زیادہ انعام لنگر سمبیوٹک تہذیب کے تقسیمی نظام کا بنیادی اصول ہے۔ یہ نہ تو لوٹ مار ازم کے &quot;طاقتور سب کچھ کھاتا ہے&quot; سے مختلف ہے، اور نہ ہی گھریلو واد کے &quot;ایک ساتھ کھانا&quot; سے مختلف ہے؛ بلکہ، یہ بنیادی ضمانت کی بنیاد پر، شراکت کے مطابق وسائل اور مواقع تقسیم کرتا ہے، اور انصاف اور کارکردگی کے اتحاد کو حاصل کرتا ہے۔ زیادہ محنت زیادہ انعام کا حتمی مقصد یہ ہے کہ ہر زندگی کی محنت کا انعام ہو، اور ہر زندگی کی صلاحیت کو مکمل طور پر ظاہر کیا جا سکے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>08-人人有路保障体系 (سب کے لیے راستے کی ضمانت کا نظام)</li><li>22-资源分配联产承包机制 (وسائل کی تقسیم کا پیداوار سے منسلک معاہدے کا طریقہ کار)</li><li>41-共生劳动法 (سمبیوٹک محنت کا قانون)</li></ul>',37)])])}const _=a(l,[["render",d]]);export{c as __pageData,_ as default};
